// Keen 1 assets in flash. Data files are GENERATED by tools/assetdump.
#ifndef KEEN1_ASSETS_H
#define KEEN1_ASSETS_H

#include <stdint.h>
#include "render/gfx.h"

extern const EGAHeadGeneralSection_T keen1_egaHead;
extern const EGAHeadUnmasked_T keen1_bmpHeads[];      // bmpNum
extern const MaskedSpriteEntry_T keen1_spriteEntries[]; // 4 * spriteNum

// One byte per pixel: bits 0-3 = EGA color index; sprites: bit 4 = mask.
extern const uint8_t keen1_tileData[];   // tileNum * 256
extern const uint8_t keen1_fontData[];   // fontNum * 64
extern const uint8_t keen1_bmpData[];
extern const uint32_t keen1_bmpOffsets[];
extern const uint8_t keen1_spriteData[];
extern const uint32_t keen1_spriteOffsets[];
extern const uint32_t keen1_spriteDataSize;

extern const uint8_t keen1_exeImage[];   // unpacked KEEN1.EXE minus MZ header
extern const uint32_t keen1_exeImageSize;

typedef struct { const char *name; const uint8_t *data; uint32_t size; } AssetFile_T;
extern const AssetFile_T keen1_files[];
extern const int keen1_filesCount;

#endif
